SELECT o.order_id, o.order_date, SUM(SUM(oi.quantity)) OVER (ORDER BY o.order_date, o.order_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_items FROM orders o JOIN order_items oi ON oi.order_id = o.order_id GROUP BY o.order_id, o.order_date ORDER BY o.order_date, o.order_id;
WITH order_totals AS (SELECT o.order_id, o.order_date, SUM(oi.quantity * p.unit_price) AS total FROM orders o JOIN order_items oi ON oi.order_id = o.order_id JOIN products p ON p.product_id = oi.product_id GROUP BY o.order_id, o.order_date) SELECT order_id, order_date, total, LAG(total) OVER (ORDER BY order_date, order_id) AS previous_total FROM order_totals;
